{
  "name": "AMI带持久电流开关的超导磁体",
  "name_en": "AMI Superconducting Magnet with Persistent Current Switch",
  "manufacturer": "American Magnetics, Inc.",
  "description": "这是一套带持久电流开关的超导磁体系统，可由外部电流源励磁，并切换到持久模式以提供稳定磁场。常用于低温实验、量子器件测试和材料测量中的磁场设定、扫场与长期稳场。",
  "description_en": "This is a superconducting magnet system with a persistent current switch. It can be energized by an external current source and switched into persistent mode to provide a stable magnetic field. It is commonly used for magnetic field biasing, field sweeps, and long-term field stability in cryogenic experiments, quantum device measurements, and materials characterization.",
  "tag_hints": [
    "superconducting magnet",
    "persistent current switch",
    "magnetic field control",
    "field sweep",
    "cryogenic experiments",
    "quantum device measurement"
  ],
  "actions": [
    {
      "action_name": "auto-BtoI",
      "description": "将目标磁场换算为对应的励磁电流。",
      "description_en": "Convert a target magnetic field to the corresponding drive current."
    },
    {
      "action_name": "auto-ItoB",
      "description": "将电流换算为对应的磁场。",
      "description_en": "Convert a current to the corresponding magnetic field."
    },
    {
      "action_name": "auto-get_switch_state",
      "description": "获取持久电流开关状态。",
      "description_en": "Get the persistent current switch state."
    },
    {
      "action_name": "auto-set_switch_state",
      "description": "设置持久电流开关状态。",
      "description_en": "Set the persistent current switch state."
    },
    {
      "action_name": "auto-get_source_current",
      "description": "获取电流源输出电流。",
      "description_en": "Get the source current."
    },
    {
      "action_name": "auto-set_source_current",
      "description": "设置电流源输出电流。",
      "description_en": "Set the source current."
    },
    {
      "action_name": "auto-get_heater_current",
      "description": "获取持久电流开关加热器电流。",
      "description_en": "Get the persistent switch heater current."
    },
    {
      "action_name": "auto-measure_field",
      "description": "测量当前磁场。",
      "description_en": "Measure the current magnetic field."
    },
    {
      "action_name": "auto-set_field",
      "description": "设置目标磁场。",
      "description_en": "Set the target magnetic field."
    },
    {
      "action_name": "auto-get_field",
      "description": "获取磁场设定值。",
      "description_en": "Get the magnetic field setpoint."
    },
    {
      "action_name": "auto-disconnect_source",
      "description": "断开电流源与磁体的连接。",
      "description_en": "Disconnect the current source from the magnet."
    },
    {
      "action_name": "auto-bring_source_to_field",
      "description": "将电流源调到与当前磁场对应的电流。",
      "description_en": "Bring the current source to the current field-equivalent current."
    },
    {
      "action_name": "auto-step_magfield_to_value",
      "description": "以步进方式将磁场调到指定值。",
      "description_en": "Step the magnetic field to a specified value."
    }
  ]
}

